class ConnectGame:
    def __init__(self, board):
        self.board = [line.strip().split() for line in board.strip().splitlines()]

    def get_winner(self):
        size = len(self.board)
        if size == 0:
            return ""
        if self._reaches(
            "X",
            {(r, 0) for r in range(size)},
            {(r, size - 1) for r in range(size)},
        ):
            return "X"
        if self._reaches(
            "O",
            {(0, c) for c in range(size)},
            {(size - 1, c) for c in range(size)},
        ):
            return "O"
        return ""

    def _reaches(self, player, start, goal):
        seen = set()
        stack = [pos for pos in start if self.board[pos[0]][pos[1]] == player]
        while stack:
            pos = stack.pop()
            if pos in seen:
                continue
            seen.add(pos)
            if pos in goal:
                return True
            r, c = pos
            for dr, dc in ((-1, -1), (-1, 0), (0, -1), (0, 1), (1, -1), (1, 0)):
                nr, nc = r + dr, c + dc
                if (
                    0 <= nr < len(self.board)
                    and 0 <= nc < len(self.board[nr])
                    and self.board[nr][nc] == player
                    and (nr, nc) not in seen
                ):
                    stack.append((nr, nc))
        return False

